seen = []
failure = ValueError('truth failure')
class Flag:
    def __bool__(self):
        seen.append('truth')
        raise failure
try:
    b2a_uu(b'a' * 0, backtick=Flag())
except ValueError as caught:
    assert caught is failure
    assert caught.args == ('truth failure',)
else:
    assert False
assert seen == ['truth']

