class Text(str):
    def __str__(self):
        raise AssertionError('coercion')
class Data(bytes):
    def __bytes__(self):
        raise AssertionError('coercion')
assert a2b_uu(Text('!    \n')) == b'\0'
assert a2b_uu(Data(b'!    \n')) == b'\0'
assert b2a_uu(Data(b'\0'), backtick=True) == b'!````\n'

seen = []
class Flag:
    def __bool__(self):
        seen.append('truth')
        raise AssertionError('truth reached')
try:
    b2a_uu('text', backtick=Flag())
except TypeError as error:
    assert error.args == ("a bytes-like object is required, not 'str'",)
else:
    assert False
assert seen == []

